UPDATE pay03_account
   SET pay03_start_date        = #{req.startDate},
       pay03_ast_class_tree_id = #{req.astClassTreeId},
       pay03_bank_cd           = #{req.bankCd},
       pay03_account_no        = #{req.accountNo},
       pay03_account_nm        = #{req.accountName},
       pay03_note              = #{req.note}
 WHERE pay03_account_id = #{req.accountId}
   AND pay03_company_id = #{companyId}

